   305→void UWjWorldPlacementComponent::SaveLayoutToSlot(const FString& SlotName)
   306→{
   307→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   308→	UWorld* World = GetWorld();
   309→	if (!World)
   310→	{
   311→		return;
   312→	}
   313→
   314→	ENetMode NetMode = World->GetNetMode();
   315→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   316→	{
   317→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayoutToSlot skipped (not host)"));
   318→		return;
   319→	}
   320→
   321→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   322→	if (!DataProvider)
   323→	{
   324→		return;
   325→	}
   326→
   327→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   328→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   329→	);
   330→
   331→	if (!SaveGame)
   332→	{
   333→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   334→		return;
   335→	}
   336→
   337→	// DataProvider의 배치 데이터 복사
   338→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   339→	SaveGame->SavedContext = CurrentContext;
   340→
   341→	if (UGameplayStatics::SaveGameToSlot(SaveGame, SlotName, 0))
   342→	{
   343→		LoadedSlotName = SlotName;
   344→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout saved to '%s' (%d objects)"),
   345→			*SlotName, SaveGame->PlacedObjects.Num());
   346→
   347→		// AW 컨텍스트인 경우 CSV도 함께 내보내기
   348→		if (CurrentContext == EPlacementContext::ApproachingWall)
   349→		{
   350→			ExportLayoutAsCSV(SlotName);
   351→		}
   352→		// JumpMap 컨텍스트인 경우 CSV도 함께 내보내기
   353→		else if (CurrentContext == EPlacementContext::JumpMap)
   354→		{
   355→			ExportJumpMapLayoutAsCSV(SlotName);
   356→		}
   357→	}
   358→	else
   359→	{
   360→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
   361→	}
   362→}
