   804→AWjWorldPlacedObjectActor* UWjWorldPlacementComponent::TraceForPlacedObject() const
   805→{
   806→	APlayerController* PC = GetPlayerController();
   807→	if (!PC)
   808→	{
   809→		return nullptr;
   810→	}
   811→
   812→	FVector WorldLocation, WorldDirection;
   813→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   814→	{
   815→		return nullptr;
   816→	}
   817→
   818→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   819→
   820→	FHitResult HitResult;
   821→	FCollisionQueryParams QueryParams;
   822→	QueryParams.bTraceComplex = false;
   823→	QueryParams.AddIgnoredActor(GetOwner());
   824→
   825→	if (GetWorld()->LineTraceSingleByChannel(HitResult, WorldLocation, TraceEnd, ECC_Visibility, QueryParams))
   826→	{
   827→		return Cast<AWjWorldPlacedObjectActor>(HitResult.GetActor());
   828→	}
   829→
   830→	return nullptr;
   831→}
