   183→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Selected object %s"), *ObjectId.ToString());
   184→	}
   185→}
   186→
   187→void UPlacementHUDWidgetBase::SetTitleText(const FText& Title)
   188→{
   189→	if (TitleText)
   190→	{
   191→		TitleText->SetText(Title);
   192→	}
   193→}
   194→
   195→void UPlacementHUDWidgetBase::SetControlsHintText(const FText& Hint)
   196→{
   197→	if (ControlsHintText)
   198→	{
   199→		ControlsHintText->SetText(Hint);
   200→	}
   201→}
   202→
   203→void UPlacementHUDWidgetBase::OnLoadClicked()
   204→{
   205→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Load clicked"));
   206→
   207→	if (!LoadDialogClass)
   208→	{
   209→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementHUDWidgetBase: LoadDialogClass not set"));
   210→		return;
   211→	}
   212→
   213→	// 이미 열려있으면 스킵
   214→	if (LoadDialogInstance && LoadDialogInstance->IsInViewport())
   215→	{
   216→		return;
   217→	}
   218→
   219→	// 다이얼로그 생성
   220→	LoadDialogInstance = CreateWidget<UPlacementLoadDialogWidget>(GetOwningPlayer(), LoadDialogClass);
   221→	if (LoadDialogInstance)
   222→	{
   223→		// 저장된 슬롯 목록 가져오기
   224→		TArray<FString> SlotNames;
   225→		if (PlacementComponent)
   226→		{
