	// 회전 입력 액션 (R)
	UPROPERTY(config, EditAnywhere, NoClear, Category = "Placement|Input")
	TSoftObjectPtr<UInputAction> PlacementRotateAction;

	// 삭제 입력 액션 (DEL)
	UPROPERTY(config, EditAnywhere, NoClear, Category = "Placement|Input")
	TSoftObjectPtr<UInputAction> PlacementDeleteAction;
};

