   894→void UWjWorldPlacementComponent::LoadInputSettings()
   895→{
   896→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   897→	if (!Settings)
   898→	{
   899→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: DeveloperSettings not found"));
   900→		return;
   901→	}
   902→
   903→	// 이미 로드된 경우 스킵
   904→	if (PlacementMappingContext)
   905→	{
   906→		return;
   907→	}
   908→
   909→	// MappingContext 로드
   910→	if (!Settings->PlacementMappingContext.IsNull())
   911→	{
   912→		PlacementMappingContext = Settings->PlacementMappingContext.LoadSynchronous();
