    73→void AWjWorldGameModeLobby::LoadCatalog()
    74→{
    75→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    76→	if (!Settings || Settings->PlaceableObjectCatalog.IsNull())
    77→	{
    78→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: No PlaceableObjectCatalog configured"));
    79→		return;
    80→	}
    81→
    82→	CachedCatalog = Settings->PlaceableObjectCatalog.LoadSynchronous();
    83→	if (!CachedCatalog)
    84→	{
    85→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("WjWorldGameModeLobby: Failed to load PlaceableObjectCatalog"));
    86→		return;
    87→	}
    88→
    89→	// GameState에도 카탈로그 설정
    90→	AWjWorldGameStateLobby* LobbyGameState = GetLobbyGameState();
    91→	if (LobbyGameState)
    92→	{
    93→		LobbyGameState->SetCatalog(CachedCatalog);
    94→	}
    95→
    96→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: Catalog loaded"));
    97→}
