   192→
   193→	// HUD 전환
   194→	AWjWorldHUDLobby* LobbyHUD = Cast<AWjWorldHUDLobby>(LobbyPC->GetHUD());
   195→	if (LobbyHUD)
   196→	{
   197→		LobbyHUD->ShowPlacementHUD(PlacementComp);
   198→	}
   199→
   200→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: Entered placement mode (Host)"));
