    24→void AWjWorldHUDLobby::ShowLobbyHUD()
    25→{
    26→	if (!LobbyHUDWidgetClass)
    27→	{
    28→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldHUDLobby: LobbyHUDWidgetClass is not set!"));
    29→		return;
    30→	}
    31→
    32→	// 이미 인스턴스가 있으면 재사용
    33→	if (LobbyHUDWidgetInstance && LobbyHUDWidgetInstance->IsInViewport())
    34→	{
    35→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldHUDLobby: Lobby HUD is already visible"));
    36→		return;
    37→	}
    38→
    39→	// 새 인스턴스 생성
    40→	LobbyHUDWidgetInstance = CreateWidget<ULobbyHUDWidget>(GetWorld(), LobbyHUDWidgetClass);
    41→
    42→	if (LobbyHUDWidgetInstance)
    43→	{
    44→		LobbyHUDWidgetInstance->AddToViewport(0); // Z-Order 0 (배경)
    45→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldHUDLobby: Lobby HUD displayed"));
    46→	}
    47→	else
