    77→	}
    78→
    79→	PlacementHUDWidgetInstance = CreateWidget<UPlacementHUDWidget>(GetWorld(), PlacementHUDWidgetClass);
    80→	if (PlacementHUDWidgetInstance)
    81→	{
    82→		PlacementHUDWidgetInstance->SetPlacementComponent(PlacementComponent);
    83→		PlacementHUDWidgetInstance->AddToViewport(0);
    84→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldHUDLobby: Placement HUD displayed"));
