    99→void AWjWorldGameModeLobby::LoadHostLayoutToGameState()
   100→{
   101→	if (!HasAuthority())
   102→	{
   103→		return;
   104→	}
   105→
   106→	AWjWorldGameStateLobby* LobbyGameState = GetLobbyGameState();
   107→	if (!LobbyGameState)
   108→	{
   109→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("WjWorldGameModeLobby: GameStateLobby not found"));
   110→		return;
   111→	}
   112→
   113→	// 호스트의 로컬 SaveGame 로드
   114→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   115→		UGameplayStatics::LoadGameFromSlot(TEXT("LobbyLayout"), 0)
   116→	);
   117→
   118→	if (SaveGame && SaveGame->PlacedObjects.Num() > 0)
   119→	{
   120→		LobbyGameState->SetPlacedObjects(SaveGame->PlacedObjects);
   121→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: Host layout loaded to GameState (%d objects)"),
   122→			SaveGame->PlacedObjects.Num());
   123→	}
   124→	else
   125→	{
   126→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: No saved layout found for host"));
   127→	}
   128→}
