   130→void AWjWorldGameModeLobby::InitializeNewPlayer(APlayerController* NewPlayer)
   131→{
   132→	if (!NewPlayer)
   133→	{
   134→		return;
   135→	}
   136→
   137→	// 마우스 커서 표시
   138→	NewPlayer->bShowMouseCursor = true;
   139→	NewPlayer->SetInputMode(FInputModeGameAndUI());
   140→
   141→	// PlacementComponent에 카탈로그 설정
   142→	AWjWorldPlayerControllerLobby* LobbyPC = Cast<AWjWorldPlayerControllerLobby>(NewPlayer);
   143→	if (LobbyPC)
   144→	{
   145→		UWjWorldPlacementComponent* PlacementComp = LobbyPC->GetPlacementComponent();
   146→		if (PlacementComp && CachedCatalog)
   147→		{
   148→			PlacementComp->SetCatalog(CachedCatalog);
   149→		}
   150→	}
   151→}
