   169→void AWjWorldGameModeLobby::EnterPlacementMode()
   170→{
   171→	APlayerController* PC = GetWorld()->GetFirstPlayerController();
   172→	AWjWorldPlayerControllerLobby* LobbyPC = Cast<AWjWorldPlayerControllerLobby>(PC);
   173→	if (!LobbyPC)
   174→	{
   175→		return;
   176→	}
   177→
   178→	// 호스트만 배치 모드 진입 가능
   179→	if (!IsHost(LobbyPC))
   180→	{
   181→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("WjWorldGameModeLobby: Only host can enter placement mode"));
   182→		return;
   183→	}
   184→
   185→	UWjWorldPlacementComponent* PlacementComp = LobbyPC->GetPlacementComponent();
   186→	if (!PlacementComp)
   187→	{
   188→		return;
   189→	}
   190→
   191→	PlacementComp->EnterPlacementMode();
   192→
   193→	// HUD 전환
   194→	AWjWorldHUDLobby* LobbyHUD = Cast<AWjWorldHUDLobby>(LobbyPC->GetHUD());
   195→	if (LobbyHUD)
   196→	{
   197→		LobbyHUD->ShowPlacementHUD(PlacementComp);
   198→	}
   199→
   200→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: Entered placement mode (Host)"));
   201→}
   202→
   203→void AWjWorldGameModeLobby::ExitPlacementMode()
   204→{
   205→	APlayerController* PC = GetWorld()->GetFirstPlayerController();
   206→	AWjWorldPlayerControllerLobby* LobbyPC = Cast<AWjWorldPlayerControllerLobby>(PC);
   207→	if (!LobbyPC)
   208→	{
   209→		return;
   210→	}
   211→
   212→	UWjWorldPlacementComponent* PlacementComp = LobbyPC->GetPlacementComponent();
   213→	if (PlacementComp)
   214→	{
   215→		PlacementComp->ExitPlacementMode();
   216→	}
   217→
   218→	// HUD 복원
   219→	AWjWorldHUDLobby* LobbyHUD = Cast<AWjWorldHUDLobby>(LobbyPC->GetHUD());
   220→	if (LobbyHUD)
   221→	{
   222→		LobbyHUD->HidePlacementHUD();
   223→	}
   224→
   225→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: Exited placement mode"));
   226→}
