   228→void AWjWorldGameModeLobby::ShowCreateRoomWindow()
   229→{
   230→	if (!CreateRoomWindowClass)
   231→	{
   232→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameModeLobby: CreateRoomWindowClass is not set!"));
   233→		return;
