   239→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeLobby: CreateRoomWindow is already open"));
   240→		return;
   241→	}
   242→
   243→	// 새 인스턴스 생성
   244→	CreateRoomWindowInstance = CreateWidget<UCreateRoomWindow>(GetWorld(), CreateRoomWindowClass);
   245→	
   246→	if (CreateRoomWindowInstance)
   247→	{
   248→		CreateRoomWindowInstance->ShowPopup();
