### 5. PlayerControllerLobby Modifications

**File**: `Source/WjWorld/Core/Local/Lobby/WjWorldPlayerControllerLobby.h`

Add members for pawn management:

```cpp
public:
    /** 배치 모드용 카메라 Pawn으로 전환 */
    void SwitchToPlacementCamera();

    /** 기존 캐릭터로 복귀 */
    void RestoreOriginalPawn();

    /** 배치 카메라 Pawn 보유 여부 */
    bool IsInPlacementCameraMode() const { return PlacementCameraPawn != nullptr; }

private:
    /** 배치 모드 중 원래 캐릭터 참조 (WeakPtr: owned by world, not by controller) */
    TWeakObjectPtr<APawn> OriginalPawn;

    /** 배치 카메라 Pawn (소유: 스폰 시 생성, 복귀 시 파괴) */
