   119→bool UWjWorldPlacementComponent::TraceAirPlane(FVector& OutLocation) const
   120→{
   121→    APlayerController* PC = GetPlayerController();
   122→    if (!PC) return false;
   123→
   124→    FVector WorldLoc, WorldDir;
   125→    if (!PC->DeprojectMousePositionToWorld(WorldLoc, WorldDir)) return false;
   126→
   127→    // Ray-plane intersection: Plane at Z = AirPlaneHeight, Normal = UpVector
   128→    float Denom = FVector::DotProduct(WorldDir, FVector::UpVector);
   129→    if (FMath::Abs(Denom) < KINDA_SMALL_NUMBER) return false; // 레이가 평면과 평행
   130→
