class AWjWorldPlacementCameraPawn; // forward decl

public:
    /** 배치 카메라 Pawn으로 전환 */
    void SwitchToPlacementCamera();
    /** 원래 캐릭터로 복귀 */
    void RestoreOriginalPawn();
    /** 카메라 모드 중인지 확인 */
    bool IsInPlacementCameraMode() const { return PlacementCameraPawn != nullptr; }

private:
    TWeakObjectPtr<APawn> OriginalPawn;

    UPROPERTY()
    TObjectPtr<AWjWorldPlacementCameraPawn> PlacementCameraPawn;
```

### .cpp 구현

**SwitchToPlacementCamera**:
1. `OriginalPawn = GetPawn()` (WeakPtr)
2. `PlayerCameraManager`에서 현재 카메라 위치/회전 가져오기 → SpawnLocation/Rotation
3. `SpawnActor<AWjWorldPlacementCameraPawn>(StaticClass(), SpawnLocation, SpawnRotation)`
4. `Possess(PlacementCameraPawn)` — 이 시점에 SetupPlayerInputComponent 호출됨
5. `SetControlRotation(SpawnRotation)` — 초기 시점 설정
6. `SetInputMode(FInputModeGameAndUI().SetHideCursorDuringCapture(false))` — 마우스 커서 유지

**RestoreOriginalPawn**:
1. `if (OriginalPawn.IsValid()) Possess(OriginalPawn.Get())` — else 로그 경고
2. `OriginalPawn.Reset()`
3. `PlacementCameraPawn->Destroy(); PlacementCameraPawn = nullptr`
4. `SetInputMode(FInputModeGameAndUI())` — 복원

